    専門 = factor(専門, levels = c("内科", "小児科")) # 水準（順序付き）にする
  ) |&gt; 
  select(日付, 曜日, 土日祝, 専門, 利用者数) |&gt; 
  mutate(日付 = as.POSIXct(日付), # 日付をデータの型が「date」になるように変形
         日付 = as.Date(日付))

